package com.connectjob.controller;
import com.connectjob.model.Application; import com.connectjob.repository.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/applications") public class ApplicationController { final ApplicationRepository apps; final JobRepository jobs; final UserRepository users; ApplicationController(ApplicationRepository a,JobRepository j,UserRepository u){apps=a;jobs=j;users=u;} @PostMapping("/jobs/{jobId}") public Application apply(@PathVariable Long jobId,Authentication auth){var u=users.findByEmail(auth.getName()).orElseThrow();if(apps.existsByJobIdAndUserId(jobId,u.getId()))throw new RuntimeException("Already applied");var a=new Application();a.setJob(jobs.findById(jobId).orElseThrow());a.setUser(u);return apps.save(a);} @GetMapping public List<Application> mine(Authentication auth){return apps.findByUserIdOrderByAppliedAtDesc(users.findByEmail(auth.getName()).orElseThrow().getId());} }
